%Block 1: Extracting data for each sheet
%Here all csvs are loaded and voltage, current, soc, and reisstance checked
% Missing timesteps where there a gap longer than .3s or any backward
% timesteps are checked. 
%Every SOC volatge and curent curve is plotted

file = 'all_sessions.xlsx';
names = sheetnames(file);

for k = 1:numel(names)
    B = readtable(file, 'Sheet', names(k), 'Range', 'A:E', 'ReadVariableNames', true);
    disp(names(k))                    
    disp(B.Properties.VariableNames)  
    data(k).name = names(k); %struct array in workspace
    data(k).t = B.time_s;
    data(k).V = B.voltage_V;
    data(k).I = B.current_A;
    data(k).soc = B.state_of_charge_pct/100;
    data(k).Rlog = B.internal_resistance_mOhm;
end

%check each file
for k = 1:numel(data)
    dt = diff(data(k).t); %checks timestep
    gaps = find(dt>0.3);
    back = find(dt<=0);
    dSOC = data(k).soc(1)-data(k).soc(end);

    fprintf('%s: %d gaps, %d bad timestamps, SOC drop = %.4f\n', ...
        data(k).name, numel(gaps), numel(back), dSOC);

    for g = gaps'
        fprintf(' gap of %.2f s at t = %.1f s\n', dt(g), data(k).t(g));

    end

end

%plot levels to check current sign

for k=1: numel(data)
    figure('Name', data(k).name);
    subplot(2, 1, 1); plot(data(k).t, data(k).V);
    ylabel('Voltage (V)');
    grid on
    title(data(k).name, 'Interpreter', 'none');
    subplot(2,1,2);
    plot(data(k).t, data(k).I);
    ylabel('Current (A)');
    xlabel('Time (s)');
    grid on
end


%OCV extraction: since evry session ended with a 10min rest the script took
%ave over last 5s as the OCV
%It compares OCV with voltage a minute earlier to see if it fully settle
for k = 1:numel(data)
    t = data(k).t;
    V = data(k).V;
    last5  = t >= t(end) - 5; 
    before = t >= t(end) - 65 & t < t(end) - 60;

    data(k).OCVend = mean(V(last5));
    data(k).SOCend = data(k).soc(end);
    drift = 1000 * (mean(V(last5)) - mean(V(before)));   % in mV

   
    fprintf('%s: OCV = %.4f V at SOC = %.4f, change over last minute = %.1f mV\n', ...
        data(k).name, data(k).OCVend, data(k).SOCend, drift);
end

%10% current flagged: there was an inteference in 10% log. This is due to
%the minimum bound on electronic load being triggered
%Script finds where current drops below 0.54A wich marks end of usable data
i10 = find(endsWith(names, '_10SOC'));   
t = data(i10).t;  I = data(i10).I;      

rowStart = find(t > 150 & I > 0.5, 1);     
rowCut = rowStart + find(I(rowStart:end) < 0.54, 1) - 2; %

data(i10).cut = rowCut;                    % store the cut point
fprintf('Cut at t = %.1f s, V = %.3f V, SOC = %.4f\n', ...
    t(rowCut), data(i10).V(rowCut), data(i10).soc(rowCut));

