%----------------------------------------------------------------------
%Finding Thevenin Parameters
%it should be noted that there was a pivot in the method going from 100-60%
%session to the 50-10% session. 
% A 10second initial gap was added for ease of doing the physical
% experiment
%Since the thevenin parameters are determined by the performance before and
%after the load is applied, the exact edges must be determined

%Find load edges: 
%if a sample is above .25A, it is load on - half current step. fair margin
%because curernt should be 0 or 0.55A
%else it is load off
%These changes are called edges

for k = 1:numel(data)
    I = data(k).I;
    n = numel(I);
    if ~isempty(data(k).cut)
        n = data(k).cut;
    end

    loadon= I(1:n)>0.25; %about half of load step. defining factor of 
    % load on or off
    change = diff(loadon); 
    %diff subtracts values in a list. Load on will only ever be true or
    %false so 0 or 1
    %Therefore if this remains 0-> load is off
    %if it is + 1 -> 0 + 1 -> Load switched on
    %if it is -1 -> 0 - 1 -> Load switched off

    data(k).onEdges = find(change==1) + 1;
    data(k).offEdges = find(change == -1) + 1;

    fprintf('%s: ON at t =%s s and OFF at t = %s s\n', data(k).name, ...
        mat2str(data(k).t(data(k).onEdges)', 4), ...
         mat2str(data(k).t(data(k).offEdges)', 4));

end
%-------------------------------------------------------------------------
%Thevenin parameters

%R0 at each edge: At edge, voltage jumps instantly
%Compare sample after edge with 5 samples before. 

for k = 1:numel(data)
    t = data(k).t;
    V = data(k).V;
    I = data(k).I;

    edges = sort([data(k).onEdges; data(k).offEdges]); %Collect every load switch in level, in time order
    R0 = nan(size(edges));

    for j = 1:numel(edges)
        e = edges(j);
        before = e-5:e-1; %takes average voltage and current over 5 samples before edge and single sample @ e+1
        dV = V(e+1) - mean(V(before)); %
        dI = I(e+1) - mean(I(before));
        R0(j) = -dV/dI *1000; %-> negative makes it positive
    end

    data(k).edgeRows = edges;
    data(k).R0edges = R0;

    fprintf('%s: R0 at edges (mOhm) = %s\n', data(k).name, mat2str(R0', 3));
    fprintf('Logged R (mOhm) at edges = %s\n', mat2str(data(k).Rlog(edges + 1)', 3));
end

allSOC = []; 
allR0 =[]; 
allRlog = [];


%RC polarisation constants

for k = 1:numel(data)
    e = data(k).edgeRows;
    allSOC = [allSOC; data(k).soc(e+1)];
    allR0 = [allR0; data(k).R0edges];
    allRlog = [allRlog; data(k).Rlog(e+1)];
end

figure('Name', 'R0 vs SOC');
plot(allSOC, allR0, 'o', allSOC, allRlog, 'x');
grid on
xlabel('SOC');
ylabel('R0 (m\Omega)');
legend('Estimated from edges', 'Emulator logged R')

%Gap from current voltage to resting voltage decreases as battery siwtches
%off for longer
%This happens exponentially
%Log graphs is straught line against time

for k = 1:numel(data)
    t = data(k).t;  
    V = data(k).V;  
    I = data(k).I;
    
    data(k).rc = [];                                  

    for j = 1:numel(data(k).offEdges)
        eOff = data(k).offEdges(j);

        eOn = data(k).onEdges(data(k).onEdges < eOff);    
        if isempty(eOn), continue, end                    
        eOn = eOn(end);

        nextOn = data(k).onEdges(data(k).onEdges > eOff); % where this rest ends
        if isempty(nextOn), last = numel(t); else, last = nextOn(1) - 1; end

        rows = eOff+1 : last;
        tr = t(rows) - t(eOff);
        Vr = V(rows);
        gap = mean(Vr(end-50:end)) - Vr;

        use = gap > 0.003 & tr < 15;
        if sum(use) < 5%skipped if fewer than 5 usuable points
            fprintf('%s: recovery %d skipped (only %d usable points)\n', data(k).name, j, sum(use));
            continue
        end

        p = polyfit(tr(use), log(gap(use)), 1);
        tau = -1/p(1); %from slope
        U10 = exp(p(2));% intercept
        ton = t(eOff) - t(eOn); 
        Ion = mean(I(eOn+2 : eOff-2));
        R1 = U10 / (Ion * (1 - exp(-ton/tau))); 
        C1 = tau / R1;

        data(k).rc(end+1, :) = [data(k).soc(eOff+1), tau, U10, R1, C1];
        fprintf('%s: edge %d  SOC=%.3f  tau=%.2f s  U10=%.1f mV  R1=%.1f mOhm  C1=%.1f F\n', ...
            data(k).name, j, data(k).soc(eOff+1), tau, 1000*U10, 1000*R1, C1);
    end
end

rcAll = vertcat(data.rc);            % rows: SOC, tau, U10, R1, C1

figure('Name', 'RC parameters vs SOC');
tl = tiledlayout(2, 2, 'TileSpacing', 'compact');

nexttile; plot(rcAll(:,1), rcAll(:,2), 'o'); grid on
ylabel('\tau_1 (s)')

nexttile; plot(rcAll(:,1), 1000*rcAll(:,3), 'o'); grid on
ylabel('U_{10} (mV)')

nexttile; plot(rcAll(:,1), 1000*rcAll(:,4), 'o'); grid on
ylabel('R_1 (m\Omega)'); xlabel('SOC')

nexttile; plot(rcAll(:,1), rcAll(:,5), 'o'); grid on
ylabel('C_1 (F)'); xlabel('SOC')

median(rcAll(:,2))
std(rcAll(:,2))

k = 6;
t = data(k).t;  V = data(k).V;
rest = t >= t(end) - 5;
std(V(rest))

% Polynomial fits of OCV, R0, R1, C1 vs SOC (Eq. 37 of Jung & Tullu)
% OCV and R0: plain polynomial, degree deg (6), evaluated over 0-1.
% R1 and C1 : polynomial fitted to log(value) so the result is always positive,
% degree degRC, and held at the edge value outside [lo, hi]


deg      = 6; % degree for OCV and R0
degRC    = 4;  % degree for log(R1) and log(C1). fitted to log so cant go negative
lo = 0.1;  
hi = 0.9;  % SOC range covered by recovery data - because data is most reliable here
soc_grid = linspace(0, 1, 101)';

rcAll = vertcat(data.rc);% columns: SOC, tau, U10, R1, C1

qty  = {'OCV', 'R0', 'R1', 'C1'};
ylab = {'OCV (V)', 'R_0 (m\Omega)', 'R_1 (m\Omega)', 'C_1 (F)'};
X    = {SOCcol(:), allSOC(:), rcAll(:,1),      rcAll(:,1)};
Y    = {OCVcol(:), allR0(:),  1000*rcAll(:,4), rcAll(:,5)};
useLog = [false false true true];   % fit log(y) and clamp for R1 and C1
degs   = [deg deg degRC degRC];

fits   = struct();
tables = struct();

figure('Name', 'Polynomial fits');
tiledlayout(2, 2, 'TileSpacing', 'compact');

for i = 1:4
    x = X{i};  
    y = Y{i};
    ok = isfinite(x) & isfinite(y);
    x = x(ok);  
    y = y(ok);
    
    %log fits and then help constant at hi and lo

    if useLog(i)
        [p, ~, mu] = polyfit(x, log(y), degs(i));
        evalfun = @(s) exp(polyval(p, min(max(s, lo), hi), [], mu));   % clamp, then exp
        fits.(qty{i}).lo = lo;  fits.(qty{i}).hi = hi;
    else
        [p, ~, mu] = polyfit(x, y, degs(i));
        evalfun = @(s) polyval(p, s, [], mu);
    end

    yfit = evalfun(x);
    yg   = evalfun(soc_grid);

    m    = degs(i) + 1; % number of polynomial coefficients
    rmse = sqrt(sum((y - yfit).^2) / (numel(y) - m));% MathWorks definition: SSE/(n-m)
    r2   = 1 - sum((y - yfit).^2) / sum((y - mean(y)).^2);

    fits.(qty{i}).p      = p;
    fits.(qty{i}).mu     = mu;
    fits.(qty{i}).deg    = degs(i);
    fits.(qty{i}).useLog = useLog(i);
    fits.(qty{i}).rmse   = rmse;
    fits.(qty{i}).r2     = r2;
    tables.(qty{i})      = yg;

    fprintf('%s: %d points, degree %d, RMSE = %.4g, R^2 = %.4f, min on 0-1 = %.4g, max on 0-1 = %.4g\n', ...
        qty{i}, numel(x), degs(i), rmse, r2, min(yg), max(yg));

    nexttile
    plot(x, y, 'o', soc_grid, yg, '-'); grid on
    xlabel('SOC'); ylabel(ylab{i}); xlim([0 1])
end

tables.R0 = min(tables.R0, 51);% cap at the physical pack's measured R0 (47-51 mOhm)

%lookup tables for battery equivalent block
save('hppc_params.mat', 'soc_grid', 'tables', 'fits', 'deg', 'degRC');

